# 21_balanced_known.R: balanced simulation with KNOWN parameters (focal predictor P carries the explicit spread-by-position interaction; N is an additive nuisance). Fixed environmental reference basis for all designs;
# independent training and test configurations (balanced over position x spread cells with several internal arrangements; or purely random sets as the comparison arm).
# Scenarios (declared before fitting): none; moderate and strong IDENTIFIABLE interactions (the contribution of the interaction OUTSIDE the additive design space has SD 0.15 and 0.40 logit units on the design configurations; endpoint coefficients nonnegative);
# redundant (negative control): interaction direction with the smallest content outside the additive design (exactly zero at k = 2; outside SD 0.05 at k >= 3, i.e. <= 0.1 of the moderate case) and a total interaction contribution as large as allowed (<= 4 logit units; 1 unit at k = 2).
# Exact experiment: y = true probability, no noise. Noisy experiment: Binomial(60) noise, 50 replicates. Fit sequence: (1) unpenalised, (2) ridge, (3) + spread/position curvature, (4) + interaction shrinkage (5e-3 empirical default; 1e-6 weak), (5) penalties selected jointly by inner validation (random 70/30 split of the training configurations).
# Every model is fitted by the package optimiser and by an independent constrained optimiser (nlminb) on the identical objective; additive and equal-endpoint interaction models have identical penalties (matched ridge). Run from final/ (ZG_LIB6 set).
source("revision_ident/00_ident_common.R"); source("revision_ident/01_balanced_design.R"); NC <- as.integer(Sys.getenv("NCORES", "9")); NREP <- as.integer(Sys.getenv("NREP", "50")); ORDERS <- c(2, 3, 4, 5, 8); TRIALS <- 60; REF <- ref_design(); SCN <- c("none", "moderate", "strong", "redundant")
SPEC <- list(spread_only = list(type = "spread_only"), additive = list(type = "additive"), interaction = list(type = "interaction", focal = "P"))
BASEC <- c(intercept = -1, P_f1 = 1.2, P_f2 = .8, P_f3 = .5, N_f1 = .9, N_f2 = .6, N_f3 = .4, P = .15, P_quadratic = -.05, P_cubic = 0, N = -.10, N_quadratic = 0, N_cubic = 0)
truth_setup <- function(k) { dd <- balanced_configs(k, 40, 7000 + k); bx <- build_X(dd$env, dd$idx, SPEC$interaction, REF); ba <- build_X(dd$env, dd$idx, SPEC$additive, REF); Xu <- bx$X[, paste0("P_f", 1:3, "_U")]; W <- qr.resid(qr(ba$X), Xu); sv <- svd(W); v1 <- sv$v[, 1] * sign(sum(sv$v[, 1])); v3 <- sv$v[, 3] * sign(sum(sv$v[, 3]))
  cf <- function(delta) { b <- setNames(rep(0, ncol(bx$X)), colnames(bx$X)); for (nm in names(BASEC)) if (nm %in% names(b)) b[nm] <- BASEC[[nm]]; for (i in 1:3) { b[paste0("P_f", i, "_L")] <- BASEC[[paste0("P_f", i)]] + max(0, -delta[i]); b[paste0("P_f", i, "_U")] <- BASEC[[paste0("P_f", i)]] + max(0, delta[i]) }; b }
  # declared outside-additive SDs (0.15 moderate, 0.40 strong) are capped by total-interaction SDs of 2 and 4 logit units (at k = 2 the identifiable part is ~2.5% of the interaction, so the declared values would need unrealistic effects; achieved values are reported)
  c_mod <- min(.15 / sd(W %*% v1), 2 / sd(Xu %*% v1)); c_str <- min(.40 / sd(W %*% v1), 4 / sd(Xu %*% v1)); tot_str <- sd(Xu %*% (c_str * v1)); c_red <- if (sd(W %*% v3) < 1e-6) 1 / sd(Xu %*% v3) else min(.05 / sd(W %*% v3), 4 / sd(Xu %*% v3))
  list(coefs = list(none = cf(c(0, 0, 0)), moderate = cf(c_mod * v1), strong = cf(c_str * v1), redundant = cf(c_red * v3)), info = data.frame(order = k, scenario = SCN, outside_additive_sd = c(0, sd(W %*% (c_mod * v1)), sd(W %*% (c_str * v1)), sd(W %*% (c_red * v3))), total_interaction_sd = c(0, sd(Xu %*% (c_mod * v1)), tot_str, sd(Xu %*% (c_red * v3))), singular_values_outside = paste(round(sv$d, 4), collapse = " "))) }
TS <- lapply(ORDERS, truth_setup); names(TS) <- ORDERS; write.csv(do.call(rbind, lapply(TS, `[[`, "info")), "revision_ident/tables/balancedB_truth_parameters_info.csv", row.names = FALSE)
write.csv(do.call(rbind, lapply(ORDERS, function(k) do.call(rbind, lapply(SCN, function(s) data.frame(order = k, scenario = s, term = names(TS[[as.character(k)]]$coefs[[s]]), value = unname(TS[[as.character(k)]]$coefs[[s]])))))), "revision_ident/tables/balancedB_true_coefficients.csv", row.names = FALSE)
avg_ep <- function(b) { for (i in 1:3) { m <- (b[paste0("P_f", i, "_L")] + b[paste0("P_f", i, "_U")]) / 2; b[paste0("P_f", i, "_L")] <- m; b[paste0("P_f", i, "_U")] <- m }; b }
# conditional contrast cells (arrangement-averaged): positions -1 / +1, spreads .8 / 1.6; N held at 0
contrast_cfg <- function(k) { rows <- list(); meta <- list(); types <- if (k == 2) "pair" else ARR; set.seed(123); for (m in c(-1, 1)) for (h in c(.8, 1.6)) for (t in types) { q <- shape_q(k, if (t == "pair") "symmetric" else t); rows[[length(rows) + 1]] <- data.frame(P = m + h * q, N = 0); meta[[length(meta) + 1]] <- data.frame(m = m, h = h, t = t) }
  list(env = do.call(rbind, rows), idx = matrix(seq_len(k * length(rows)), length(rows), k, byrow = TRUE), meta = do.call(rbind, meta)) }
CC <- lapply(ORDERS, contrast_cfg); names(CC) <- ORDERS
contr_from <- function(k, spec, coef, avg = FALSE) { cc <- CC[[as.character(k)]]; bx <- build_X(cc$env, cc$idx, spec, REF); b <- if (avg && spec$type == "interaction") avg_ep(coef) else coef; eta <- pred_eta(bx, b); mt <- cc$meta; f <- function(m, h) mean(eta[mt$m == m & mt$h == h]); r <- function(m, h) mean(plogis(eta[mt$m == m & mt$h == h])); d <- function(m) f(m, 1.6) - f(m, .8); dr <- function(m) r(m, 1.6) - r(m, .8)
  c(link_did = d(1) - d(-1), resp_did = dr(1) - dr(-1), link_hi = d(1), link_lo = d(-1)) }
SEL_GRID <- expand.grid(spread_smooth = c(2e-4, 2e-3, 2e-2), interaction_shrink = c(5e-3, 1e-4, 1e-6))
fit_both <- function(bx, y, w, svec, indep = TRUE) { P <- pen_matrix(bx, as.list(svec)); a <- fit_pkg(bx, y, w, P); b <- if (indep) fit_indep(bx, y, w, P, start = a$coef) else NULL; list(pkg = a, ind = b, P = P) }
select_pen <- function(btr_fun, y, w, kind, seed) { set.seed(seed); n <- length(y); inn <- sample(n, round(.7 * n)); out <- setdiff(seq_len(n), inn); grid <- if (kind == "interaction") SEL_GRID else unique(SEL_GRID["spread_smooth"]); best <- NULL
  Xall <- btr_fun(); for (g in seq_len(nrow(grid))) { sv <- c(ridge = 1e-4, spread_smooth = grid$spread_smooth[g], position_smooth = grid$spread_smooth[g], interaction_shrink = if (kind == "interaction") grid$interaction_shrink[g] else 0); sub <- Xall; sub$X <- Xall$X[inn, , drop = FALSE]; P <- pen_matrix(Xall, as.list(sv)); f <- fit_pkg(sub, y[inn], w[inn], P); eta <- drop(Xall$X[out, , drop = FALSE] %*% f$coef); dv <- bdev(y[out], plogis(eta), w[out]); if (is.null(best) || dv < best$dev) best <- list(dev = dv, sv = sv, g = grid[g, ]) }; best }
one <- function(job) { k <- job$k; sc <- job$sc; rep <- job$rep; arm <- job$arm; exact <- job$exact; b_true <- TS[[as.character(k)]]$coefs[[sc]]; sd0 <- 31000L + 1000L * k + rep + 100000L * (arm == "random"); mk <- function(seed) if (arm == "balanced") balanced_configs(k, 30, seed) else random_configs(k, 1260, seed)
  tr <- mk(sd0); te <- mk(sd0 + 500000L); out <- list(); coefs <- list(); bt <- build_X(tr$env, tr$idx, SPEC$interaction, REF); bte <- build_X(te$env, te$idx, SPEC$interaction, REF); eta_tr <- pred_eta(bt, b_true); eta_te <- pred_eta(bte, b_true); p_tr <- plogis(eta_tr); p_te <- plogis(eta_te)
  set.seed(rep * 17 + k); y_tr <- if (exact) p_tr else rbinom(length(p_tr), TRIALS, p_tr) / TRIALS; y_te <- if (exact) p_te else rbinom(length(p_te), TRIALS, p_te) / TRIALS; w_tr <- rep(if (exact) 1 else TRIALS, length(y_tr)); w_te <- rep(if (exact) 1 else TRIALS, length(y_te)); mu0 <- sum(w_tr * y_tr) / sum(w_tr)
  tcon <- contr_from(k, SPEC$interaction, b_true); tcon_avg <- contr_from(k, SPEC$interaction, b_true, avg = TRUE); delta_true <- b_true[paste0("P_f", 1:3, "_U")] - b_true[paste0("P_f", 1:3, "_L")]
  # additive design on test/train for the outside-additive component
  ba_te <- build_X(te$env, te$idx, SPEC$additive, REF); Xu_te <- bte$X[, paste0("P_f", 1:3, "_U")]; c_true <- qr.resid(qr(ba_te$X), Xu_te %*% delta_true)
  for (model in names(SPEC)) { sp <- SPEC[[model]]; btm <- build_X(tr$env, tr$idx, sp, REF); btem <- build_X(te$env, te$idx, sp, REF); rk <- qr(btm$X)$rank; s_sv <- svd(sweep(btm$X, 2, sqrt(colSums(btm$X^2)), "/"), nu = 0)$d; cond <- max(s_sv) / min(s_sv)
    stages <- if (model == "interaction") c("unpenalised", "ridge", "curvature", "shrink", "weakshrink", "selected") else c("unpenalised", "ridge", "curvature", "selected")
    for (st in stages) { svec <- if (st == "selected") { sel <- select_pen(function() btm, y_tr, w_tr, model, 5000 + rep + k); sel$sv } else STAGES[[st]]; if (model != "interaction" && st != "selected") svec[["interaction_shrink"]] <- 0
      fb <- tryCatch(fit_both(btm, y_tr, w_tr, svec, indep = TRUE), error = function(e) NULL); if (is.null(fb)) next; for (opt in c("pkg", "ind")) { f <- fb[[if (opt == "pkg") "pkg" else "ind"]]; if (is.null(f)) next; co <- f$coef; eta <- pred_eta(btem, co); p <- plogis(eta)
        r <- data.frame(arm = arm, exact = exact, replicate = rep, scenario = sc, order = k, model = model, stage = st, optimiser = opt, rank = rk, n_parameters = ncol(btm$X), scaled_condition = cond, D2_test = d2_frac(y_te, p, w_te, mu0), D2_oracle = d2_frac(y_te, p_te, w_te, mu0), rmse_link_vs_truth = sqrt(mean((eta - eta_te)^2)), rmse_resp_vs_truth = sqrt(mean((p - p_te)^2)), objective = if (!is.null(f$obj)) f$obj else NA, converged = isTRUE(f$converged), sel_spread_smooth = if (st == "selected") sel$sv[["spread_smooth"]] else NA, sel_interaction_shrink = if (st == "selected" && model == "interaction") sel$sv[["interaction_shrink"]] else NA)
        ce <- contr_from(k, sp, co); cea <- if (model == "interaction") contr_from(k, sp, co, avg = TRUE) else ce; r$est_link_did <- ce[["link_did"]]; r$est_resp_did <- ce[["resp_did"]]; r$est_link_did_explicit <- ce[["link_did"]] - cea[["link_did"]]; r$est_resp_did_explicit <- ce[["resp_did"]] - cea[["resp_did"]]
        r$true_link_did <- tcon[["link_did"]]; r$true_resp_did <- tcon[["resp_did"]]; r$true_link_did_explicit <- tcon[["link_did"]] - tcon_avg[["link_did"]]; r$true_resp_did_explicit <- tcon[["resp_did"]] - tcon_avg[["resp_did"]]
        if (model == "interaction") { dh <- co[paste0("P_f", 1:3, "_U")] - co[paste0("P_f", 1:3, "_L")]; c_hat <- qr.resid(qr(ba_te$X), Xu_te %*% dh); r$outside_sd_est <- sd(c_hat); r$outside_sd_true <- sd(c_true); r$outside_cor <- if (sd(c_hat) > 1e-9 && sd(c_true) > 1e-9) cor(c_hat, c_true) else NA; r$outside_rmse <- sqrt(mean((c_hat - c_true)^2)); r$delta_sum_est <- sum(dh); r$delta_sum_true <- sum(delta_true); r$delta_rmse <- sqrt(mean((dh - delta_true)^2)) }
        out[[length(out) + 1]] <- r }
      if (st %in% c("shrink", "curvature") && model != "spread_only") { pc <- fb$pkg$coef; ic <- fb$ind$coef; coefs[[length(coefs) + 1]] <- data.frame(arm = arm, exact = exact, replicate = rep, scenario = sc, order = k, model = model, stage = st, max_coef_diff_pkg_vs_indep = max(abs(pc - ic)), max_pred_diff_pkg_vs_indep = max(abs(pred_eta(btem, pc) - pred_eta(btem, ic))), obj_diff = fb$pkg$obj - fb$ind$obj) } } }
  list(r = bind_rows(out), c = bind_rows(coefs)) }
jobs <- list(); for (arm in c("balanced", "random")) for (k in ORDERS) for (sc in SCN) { jobs[[length(jobs) + 1]] <- list(arm = arm, k = k, sc = sc, rep = 0L, exact = TRUE); for (r in seq_len(NREP)) jobs[[length(jobs) + 1]] <- list(arm = arm, k = k, sc = sc, rep = r, exact = FALSE) }
if (nzchar(Sys.getenv("ONLY"))) jobs <- jobs[as.integer(strsplit(Sys.getenv("ONLY"), ",")[[1]])]; t0 <- Sys.time(); RES <- mclapply(jobs, function(j) tryCatch(one(j), error = function(e) { message("ERR ", paste(unlist(j), collapse = " "), ": ", conditionMessage(e)); NULL }), mc.cores = NC, mc.preschedule = FALSE); cat("elapsed", format(Sys.time() - t0), "jobs", length(jobs), "bad", sum(vapply(RES, is.null, TRUE)), "\n")
R <- bind_rows(lapply(RES, function(x) if (!is.null(x)) x$r)); Cm <- bind_rows(lapply(RES, function(x) if (!is.null(x)) x$c)); sfx <- if (nzchar(Sys.getenv("ONLY"))) "_test" else ""; write.csv(R, sprintf("revision_ident/tables/balancedB_fits%s.csv", sfx), row.names = FALSE); write.csv(Cm, sprintf("revision_ident/tables/balancedB_optimiser_agreement%s.csv", sfx), row.names = FALSE); cat("rows", nrow(R), "\n")
